/*
 * Access to the game files (Half-Life/CS folder or assets/), plus the TGA
 * reader used for the skybox.
 */
(function (root) {
  'use strict';
  const NS = (root.CSDemo = root.CSDemo || {});

  class GameFiles {
    constructor() {
      this.files = new Map(); // '/lowercase/path' -> File | {url}
      this.source = '';
    }

    /** Reads assets/manifest.json (generated by tools/copy_game_files.py). */
    async loadManifest(base) {
      base = base || 'assets/';
      try {
        const r = await fetch(base + 'manifest.json', { cache: 'no-cache' });
        if (!r.ok) return false;
        const m = await r.json();
        for (const f of m.files || []) this.files.set('/assets/' + f.toLowerCase(), { url: base + f });
        this.source = 'assets/';
        return this.files.size > 0;
      } catch (e) {
        return false; // opened via file:// or without the assets folder
      }
    }

    get size() { return this.files.size; }

    add(fileList) {
      this.source = 'pasta escolhida';
      for (const f of fileList) {
        const rel = (f.webkitRelativePath || f.name).replace(/\\/g, '/').toLowerCase();
        this.files.set('/' + rel, f);
      }
    }

    /** Looks up `rel` (e.g. "maps/de_dust2.bsp"), preferring cstrike, then valve. */
    find(rel) {
      rel = rel.replace(/\\/g, '/').toLowerCase().replace(/^\/+/, '');
      const prefs = ['/cstrike/' + rel, '/valve/' + rel];
      for (const p of prefs) {
        for (const [k, f] of this.files) if (k.endsWith(p)) return f;
      }
      for (const [k, f] of this.files) if (k.endsWith('/' + rel) && !/_hd\//.test(k)) return f;
      for (const [k, f] of this.files) if (k.endsWith('/' + rel)) return f;
      return null;
    }

    async read(rel) {
      const f = this.find(rel);
      if (!f) return null;
      if (f.url) {
        const r = await fetch(f.url);
        return r.ok ? r.arrayBuffer() : null;
      }
      return f.arrayBuffer();
    }

    has(rel) { return !!this.find(rel); }

    hasGame() {
      for (const k of this.files.keys()) if (/\/cstrike\/maps\/[^/]+\.bsp$/.test(k)) return true;
      return false;
    }
  }

  /** 24/32-bit TGA, uncompressed or RLE. Returns {width,height,rgba} with row 0 at the top. */
  function decodeTga(buffer) {
    const u8 = new Uint8Array(buffer);
    const idLen = u8[0];
    const type = u8[2];
    const w = u8[12] | (u8[13] << 8);
    const h = u8[14] | (u8[15] << 8);
    const bpp = u8[16] >> 3;
    const topDown = (u8[17] & 0x20) !== 0;
    if ((type !== 2 && type !== 10) || (bpp !== 3 && bpp !== 4)) throw new Error('unsupported TGA');
    const px = new Uint8Array(w * h * 4);
    let p = 18 + idLen;
    let i = 0;
    const put = (b, g, r, a) => {
      const row = Math.floor(i / w), col = i % w;
      const y = topDown ? row : h - 1 - row;
      const o = (y * w + col) * 4;
      px[o] = r; px[o + 1] = g; px[o + 2] = b; px[o + 3] = a;
      i++;
    };
    if (type === 2) {
      while (i < w * h) { put(u8[p], u8[p + 1], u8[p + 2], bpp === 4 ? u8[p + 3] : 255); p += bpp; }
    } else {
      while (i < w * h && p < u8.length) {
        const hdr = u8[p++];
        const n = (hdr & 0x7f) + 1;
        if (hdr & 0x80) {
          const b = u8[p], g = u8[p + 1], r = u8[p + 2], a = bpp === 4 ? u8[p + 3] : 255;
          p += bpp;
          for (let k = 0; k < n; k++) put(b, g, r, a);
        } else {
          for (let k = 0; k < n; k++) { put(u8[p], u8[p + 1], u8[p + 2], bpp === 4 ? u8[p + 3] : 255); p += bpp; }
        }
      }
    }
    return { width: w, height: h, rgba: px };
  }

  /**
   * Texture.onUpdate hook: once a texture is on the GPU, drop the CPU-side pixel copy.
   * (Map, lightmap, model and sprite textures were otherwise stored twice.)
   */
  NS.dropCpuCopy = function (tex) {
    if (tex.image && tex.image.data) tex.image = { data: null, width: tex.image.width, height: tex.image.height };
  };

  NS.GameFiles = GameFiles;
  NS.decodeTga = decodeTga;
})(typeof window !== 'undefined' ? window : globalThis);
